import { createLogger } from '../utils/logger.js';

const logger = createLogger('COMMITMENTS');

/**
 * CommitmentMemory — "promises and commitments."
 *
 * When the owner asks for something to do later ("build a fence later", "don't forget
 * to gather stone"), the bot stores it as a commitment. Later, it may recall it on its own.
 * Over time, details fade (living memory): an old commitment
 * returns with a note that some details are fuzzy — the exact wording is always
 * generated by the LLM; there are NO canned phrases here.
 *
 * Stored in the existing `facts` table (category='commitment'); no new database.
 */
export class CommitmentMemory {
  constructor(memoryManager) {
    this.mm = memoryManager;
    this.lt = memoryManager?.longTerm || null;
  }

  _key(id) {
    return `commitment:${id}`;
  }

  /**
   * Remember a commitment. `text` is the essence of the request in your own words (not a bot reply).
   */
  remember(text, { requestedBy = null, importance = 0.6 } = {}) {
    if (!this.lt || !text) return null;
    try {
      const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
      const record = {
        id,
        text: String(text).slice(0, 240),
        requestedBy,
        importance,
        createdAt: Date.now(),
        done: false,
      };
      this.lt.setFact(this._key(id), record, 'commitment');
      logger.info(`[COMMITMENT] Remembered commitment: "${record.text}"`);
      return record;
    } catch (err) {
      logger.warn(`Failed to save commitment: ${err.message}`);
      return null;
    }
  }

  /**
   * All active (incomplete) commitments, newest first.
   */
  listOpen() {
    if (!this.lt) return [];
    try {
      const rows = this.lt.getAllFacts().filter(r => r.category === 'commitment');
      const out = [];
      for (const r of rows) {
        let rec;
        try { rec = JSON.parse(r.value); } catch { continue; }
        if (rec && !rec.done) out.push(rec);
      }
      return out.sort((a, b) => b.createdAt - a.createdAt);
    } catch (err) {
      logger.debug(`listOpen error: ${err.message}`);
      return [];
    }
  }

  /**
   * Mark a commitment as completed (or cancelled).
   */
  resolve(id) {
    if (!this.lt || !id) return false;
    try {
      const raw = this.lt.getFact(this._key(id));
      if (!raw) return false;
      const rec = typeof raw === 'string' ? JSON.parse(raw) : raw;
      rec.done = true;
      rec.resolvedAt = Date.now();
      this.lt.setFact(this._key(id), rec, 'commitment');
      return true;
    } catch (err) {
      logger.debug(`resolve error: ${err.message}`);
      return false;
    }
  }

  /**
   * Ready-to-use context for the LLM: what the bot promised but has not done yet.
   * Older commitments (> ~20 minutes of real time) are marked as hazy,
   * so the model can recall them uncertainly, like a real person. The actual
   * message is written by the model; this stores only facts and a clarity marker.
   */
  getContextForPrompt(now = Date.now()) {
    const open = this.listOpen();
    if (open.length === 0) return null;
    const lines = open.slice(0, 5).map(rec => {
      const ageMin = (now - rec.createdAt) / 60000;
      const hazy = ageMin > 20; // detail has become hazy
      const who = rec.requestedBy ? ` (requested by ${rec.requestedBy})` : '';
      return hazy
        ? `- ${rec.text}${who} [from a while ago; details are fuzzy]`
        : `- ${rec.text}${who}`;
    });
    return `You promised to do the following but have not done it yet:\n${lines.join('\n')}`;
  }
}
